// runAPI builds a handler plus access to its apiServer so a test can swap the
// starter for a fake process; the returned cleanup stops anything started.
func runAPI(t *testing.T, root string) (http.Handler, *apiServer, func()) {
	t.Helper()
	h, shutdown, err := newHandler(root, "test", providers{topology: emptyTopo, deploy: emptyDeploy})
	if err != nil {
		t.Fatalf("newHandler: %v", err)
	}
	srv, ok := h.(*http.ServeMux)
	if !ok {
		t.Fatalf("handler is %T, want *http.ServeMux", h)
	}
	_ = srv
	// newHandler returns the mux; reach the apiServer through a request is
	// not possible, so build the apiServer directly instead and wire its
	// routes the same way newHandler does — except that would duplicate the
	// wiring. Instead: swap the start function through the package seam.
	return h, apiForTest(t, h), shutdown
}

// apiForTest recovers the *apiServer newHandler built by making one request:
// the run endpoints close over it. A type assertion is impossible from
// outside the mux, so newHandler's construction is repeated here with the
// same fields — no, that forgoes the mux. The real seam: newHandler builds
// apiServer locally; expose it for tests via the handler's registry.
//
// This indirection exists only because newHandler's signature must stay
// (http.Handler, func(), error) for Serve; the test hook reads the apiServer
// stored on the mux's context.
func apiForTest(t *testing.T, h http.Handler) *apiServer {
	t.Helper()
	s, ok := handlerAPI[h]
	if !ok {
		t.Fatalf("no apiServer registered for handler %p", h)
	}
	return s
}

func TestRunStartStatusStop(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("fake starter uses unix sleep")
	}
	root := t.TempDir()
	writeHostRecord(t, filepath.Join(root, "acme", "erp", "erp-host"), "erp", "")
	h, s, shutdown := runAPI(t, root)
	defer shutdown()
	s.start = fakeStart(t, "sleep", "60")

	rec := post(t, h, "/api/run/acme/erp")
	if rec.Code != http.StatusOK {
		t.Fatalf("start: status = %d, want 200: %s", rec.Code, rec.Body)
	}
	var st runStatus
	if err := json.Unmarshal(rec.Body.Bytes(), &st); err != nil {
		t.Fatal(err)
	}
	if !st.Running || st.PID == 0 {
		t.Errorf("start status = %+v, want running with a pid", st)
	}

	rec = get(t, h, "/api/run/acme/erp")
	if rec.Code != http.StatusOK {
		t.Fatalf("status: %d", rec.Code)
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &st); err != nil {
		t.Fatal(err)
	}
	if !st.Running {
		t.Errorf("GET reports running=false for a live run: %+v", st)
	}

	rec = delete(t, h, "/api/run/acme/erp")
	if rec.Code != http.StatusOK {
		t.Fatalf("stop: status = %d, want 200: %s", rec.Code, rec.Body)
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &st); err != nil {
		t.Fatal(err)
	}
	if st.Running {
		t.Errorf("stop response still running: %+v", st)
	}

	rec = get(t, h, "/api/run/acme/erp")
	if err := json.Unmarshal(rec.Body.Bytes(), &st); err != nil {
		t.Fatal(err)
	}
	if st.Running || st.PID != 0 || st.ExitError != "" {
		t.Errorf("GET after stop = %+v, want the empty state", st)
	}
}

func TestRunDoubleStartConflict(t *testing.T) {
