// statusOf renders the map entry (or its absence) as the API payload. sysDir
// is the workspace-relative identifier; handle may be nil.
func statusOf(sysDir string, run *systemRun) runStatus {
	st := runStatus{System: sysDir, Logs: []string{}}
	if run == nil {
		return st
	}
	if h := run.handle; h != nil {
		st.StartedAt = h.started.UTC().Format(time.RFC3339)
		st.Logs = h.pump.tail()
		if run.err == nil {
			st.Running = true
			st.PID = h.pid
			return st
		}
	}
	if run.err != nil {
		st.ExitError = run.err.Error()
	}
	return st
}

