// The banner's host re-assembly (sys update / sys create) in flight.
const [syncing, setSyncing] = useState(false)
const [syncError, setSyncError] = useState<string | null>(null)
// The selected system's host process, as the dashboard last knew it, plus
// the start/stop click in flight and the run log panel's visibility.
const [run, setRun] = useState<RunState | null>(null)
const [runBusy, setRunBusy] = useState(false)
const [runError, setRunError] = useState<string | null>(null)
const [logsOpen, setLogsOpen] = useState(false)

// A different system means different topics/ports — drop the inspector,
// any half-open create drawer, and stale sync/run errors.
useEffect(() => {
  setInspect(null)
  setDraft(null)
  setSyncError(null)
  setRunError(null)
}, [system])

const sysDir = system === WORKSPACE_KEY ? '.' : system
const hasHost = (systemList ?? []).some((s) => s.path === sysDir)

// Track the selected system's host process: once when the selection lands,
// then on an interval while the dashboard says it is running — a crash
// surfaces without the user clicking anything. The effect re-keys on the
// running transition so a start/stop click resets the cadence immediately.
useEffect(() => {
  if (!sysDir || !hasHost) {
    setRun(null)
    return
  }
  let alive = true
  const pull = () =>
    api
      .runState(sysDir)
      .then((st) => {
        if (alive) setRun(st)
      })
      .catch(() => {})
  pull()
  const tick = run?.running ? setInterval(pull, 2000) : undefined
  return () => {
    alive = false
    if (tick) clearInterval(tick)
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [sysDir, hasHost, run?.running])

const runClick = () => {
  if (!sysDir || runBusy) return
  setRunBusy(true)
  setRunError(null)
  const call = run?.running ? api.stopSystem(sysDir) : api.startSystem(sysDir)
  call
    .then(setRun)
    .catch((e: unknown) => setRunError(e instanceof Error ? e.message : String(e)))
    .finally(() => setRunBusy(false))
}

