edits.oldText:
// Track the selected system's host process: once when the selection lands,
// then on an interval while the dashboard says it is running — a crash
// surfaces without the user clicking anything. The effect re-keys on the
// running transition so a start/stop click resets the cadence immediately.
useEffect(() => {
  if (!sysDir || !hasHost) {
    setRun(null)
    return
  }
  let alive = true
  const pull = () =>
    api
      .runState(sysDir)
      .then((st) => {
        if (alive) setRun(st)
      })
      .catch(() => {})
  pull()
  const tick = run?.running ? setInterval(pull, 2000) : undefined
  return () => {
    alive = false
    if (tick) clearInterval(tick)
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [sysDir, hasHost, run?.running])

edits.newText:
// Track the selected system's host process. Poll on a steady interval
// while a host is selected so a start, stop, or crash surfaces without the
// user clicking anything; start/stop clicks also set the state directly
// from their response, so the interval only ever reconciles.
useEffect(() => {
  if (!sysDir || !hasHost) {
    setRun(null)
    return
  }
  let alive = true
  const pull = () =>
    api
      .runState(sysDir)
      .then((st) => {
        if (alive) setRun(st)
      })
      .catch(() => {})
  pull()
  const tick = setInterval(pull, 2000)
  return () => {
    alive = false
    clearInterval(tick)
  }
}, [sysDir, hasHost])

